function fusionar(base, ...capas) {
  return capas.reduce((acc, capa) => {
    Object.entries(capa || {}).forEach(([clave, valor]) => {
      acc[clave] = valor && typeof valor === 'object' && !Array.isArray(valor) ? fusionar(acc[clave] || {}, valor) : valor;
    });
    return acc;
  }, {...base});
}

const translations = Object.fromEntries(Object.keys(catalog).map(language => [
  language,
  {...fusionar(catalog.es, catalog[language], complementos[language]), extra: fusionar(extraCopy.es, extraCopy[language])},
]));

export function useDirectorCopy() {
  const {language} = useLanguage();
  return translations[language] || translations.es;
}
